 $('#dgo').onclick=()=>{if(F.includes(id)){if(!can(id)){openInv();return}ST.fi=F.indexOf(id);save();go('focus')}else{if(!can(id)){openInv();return}ST.sn=N.indexOf(id);save();go('sleep')}};
